  /// \param[in,out] size Pointer to the size of the `config_value` buffer. See above comments for details.
  ///
  /// \snippet{doc} snippets.dox OrtStatus Return Value
  /// \since Version 1.14
  external ffi.Pointer<
    ffi.NativeFunction<
