        ffi.Pointer<OrtEnv> env,
        ffi.Pointer<ffi.Pointer<OrtHardwareDevice>> devices,
        ffi.Size num_devices,
      )
    >
  >
  GetHardwareDevices;

  /// \brief Check for known incompatibility issues between hardware device and a specific execution provider.
